import{_ as i,o as t,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const S=JSON.parse('{"title":"2019-10-03 :: Ceph Performance Meeting","description":"","frontmatter":{"title":"2019-10-03 :: Ceph Performance Meeting","date":"2019-10-03T00:00:00.000Z","updated":"2019-10-21T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","功能开发","测试与验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-10-03_-_-_Ceph_Performance_Meeting.md","filePath":"posts/2019/2019-10-03_-_-_Ceph_Performance_Meeting.md","lastUpdated":1780460162000}'),o={name:"posts/2019/2019-10-03_-_-_Ceph_Performance_Meeting.md"};function n(s,l,g,a,p,u){return t(),e("div",null,[...l[0]||(l[0]=[r("<p>subtitle: &quot;2019-10-03_-_-_Ceph_Performance_Meeting&quot;</p><p>会议纪要</p><p><strong>会议时间</strong>： 2023年11月某日</p><p><strong>参会人员</strong>： Sage, Igor, Adam, Mark, Casey, Ellen, Marcus, 等</p><p><strong>会议主题</strong>： Ceph分布式存储项目进展及讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、议题一：存储性能优化</strong></p><ul><li><strong>磁盘配置</strong>： <ul><li>探讨使用16K金属尺寸和间距对硬盘和NVMe驱动器的性能影响。初步测试表明，性能表现与使用16K金属尺寸相当，但间距带来的收益巨大，建议采用。</li><li>Igor对硬盘进行了测试，初步结果良好，但需要进一步验证。</li></ul></li><li><strong>性能测试</strong>： <ul><li>Sage在Luminous和Nautilus代码库上对SSD进行了大量测试，结果与NVMe的测试结果一致，性能表现相当。</li><li>Adam更新了性能测试数据，展示了使用SSD时的CPU使用率。</li></ul></li><li><strong>性能优化</strong>： <ul><li>Eric正在对CLS或RGW进行过滤优化，以减少发送给GW的数据量，但担心解码开销。</li><li>Casey提到重新排列存储桶目录条目，以仅解码需要过滤的部分，而不是整个条目。</li><li>Adam对性能进行了基准测试，并修复了一些bug，目前PR已通过测试。</li></ul></li><li><strong>其他优化</strong>： <ul><li>Margie和Ping有一个互斥锁竞争的PR，理论上可以改善某些性能问题，但需要进一步验证。</li><li>Igor更新了智能DB空间使用框架，以改进SS文件的新位置决策。</li></ul></li></ul><p><strong>二、议题二：功能开发</strong></p><ul><li><strong>存储池自动缩放</strong>： <ul><li>Sage提出将PG自动缩放与旧式存储池兼容，以避免在集群中创建大量空存储池时缩放。</li></ul></li><li><strong>OSD性能跟踪器</strong>： <ul><li>Sage建议禁用OSD性能跟踪器，因为它可能对性能产生负面影响。</li></ul></li><li><strong>文件系统创建</strong>： <ul><li>讨论在RBD上创建文件系统时的性能问题，并决定推迟优化，专注于实际使用场景。</li></ul></li><li><strong>加密性能</strong>： <ul><li>讨论加密对性能的影响，并决定进一步研究。</li></ul></li></ul><p><strong>三、议题三：其他</strong></p><ul><li><strong>新节点</strong>： <ul><li>新的Intel节点已到位，将用于测试和开发。</li></ul></li><li><strong>Sharding</strong>： <ul><li>Adam正在对数据库进行性能基准测试，并尝试调整fao以处理更多数据。</li></ul></li><li><strong>测试</strong>： <ul><li>讨论了在新的Intel节点上进行测试的计划，包括对HS性能进行测试。</li></ul></li></ul><p><strong>四、行动计划</strong></p><ul><li>确认磁盘配置和性能测试结果。</li><li>进一步研究性能优化方案。</li><li>完成功能开发。</li><li>进行新节点的测试和开发。</li><li>完成Sharding和测试工作。</li></ul><p><strong>五、后续行动</strong></p><ul><li>Sage将更新Trello板，包括所有性能优化方案。</li><li>Adam将继续进行性能基准测试和fao调整。</li><li>Igor将继续更新智能DB空间使用框架。</li><li>Sage将跟进PG自动缩放和OSD性能跟踪器的问题。</li><li>Marcus将研究加密对性能的影响。</li><li>新节点将用于测试和开发。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到了大量Ceph相关的英文关键词，如OSD、PG、CLS、RGW、RBD、SSD、NVMe等。</li><li>会议纪要仅为总结，具体细节请参考会议录音或相关文档。</li></ul>",18)])])}const c=i(o,[["render",n]]);export{S as __pageData,c as default};
